import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const geistSans = Geist({ variable: "--font-geist-sans", subsets: ["latin"] });
const geistMono = Geist_Mono({ variable: "--font-geist-mono", subsets: ["latin"] });

export const metadata: Metadata = {
  title: "Night Shift — the on-call engineer for your AI agents",
  description:
    "Night Shift detects incidents in production AI agents, traces them to the change and the coding-agent prompt behind it, prices the damage, contains it within a pre-approved policy, and only wakes you for decisions that can't be undone.",
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="en">
      <body className={`${geistSans.variable} ${geistMono.variable} min-h-screen antialiased`}>{children}</body>
    </html>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { WindowFrame } from "./ui";

export type ReelEvent = { t: number; kind: string; title: string };

const KIND_STYLE: Record<string, { tag: string; color: string }> = {
  detect: { tag: "DETECT", color: "var(--alert)" },
  investigate: { tag: "INVESTIGATE", color: "var(--info)" },
  step: { tag: "TOOL", color: "var(--faint)" },
  diagnosis: { tag: "DIAGNOSIS", color: "var(--violet)" },
  impact: { tag: "PRICE", color: "var(--amber)" },
  decide: { tag: "POLICY", color: "var(--info)" },
  propose: { tag: "PROPOSE", color: "var(--faint)" },
  act: { tag: "ACT", color: "var(--ok)" },
  verify: { tag: "VERIFY", color: "var(--ok)" },
  regression: { tag: "TEST", color: "var(--faint)" },
  detection: { tag: "NEATLOGS", color: "var(--faint)" },
  page: { tag: "PAGE", color: "var(--amber)" },
  defer: { tag: "DEFER", color: "var(--amber)" },
  resolved: { tag: "RESOLVED", color: "var(--ok)" },
  undo: { tag: "UNDO", color: "var(--alert)" },
};

function clockAt(base: string, seconds: number) {
  const [h, m] = base.split(":").map(Number);
  const total = h * 3600 + m * 60 + 12 + Math.round(seconds);
  const hh = Math.floor(total / 3600) % 24;
  const mm = Math.floor(total / 60) % 60;
  const ss = total % 60;
  return `${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`;
}

/** Replays a real incident timeline from the benchmark evidence, line by line, on loop. */
export default function IncidentReel({ events, title, base = "03:07" }: { events: ReelEvent[]; title: string; base?: string }) {
  const shown = useMemo(
    () => events.filter((e) => !(e.kind === "step" && e.title.startsWith("think"))).slice(0, 18),
    [events],
  );
  const [n, setN] = useState(0);
  useEffect(() => {
    setN(0);
    if (!shown.length) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) {
      setN(shown.length);
      return;
    }
    let i = 0;
    const t = setInterval(() => {
      i += 1;
      if (i > shown.length + 6) i = 0;
      setN(Math.min(i, shown.length));
    }, 650);
    return () => clearInterval(t);
  }, [shown]);

  return (
    <WindowFrame title={title} className="w-full">
      <div className="h-[340px] overflow-hidden px-4 py-3 font-mono text-[12px] leading-[1.55]">
        {shown.slice(0, n).map((e, i) => {
          const s = KIND_STYLE[e.kind] ?? { tag: e.kind.toUpperCase(), color: "var(--faint)" };
          const text = e.kind === "step" ? e.title.replace(/^(\w+):\s*/, "$1 → ") : e.title;
          return (
            <div key={i} className="slide-in flex gap-3">
              <span className="shrink-0 text-white/30">{clockAt(base, e.t)}</span>
              <span className="w-[86px] shrink-0" style={{ color: s.color }}>
                {s.tag}
              </span>
              <span className={`min-w-0 ${e.kind === "step" ? "text-white/45" : "text-white/85"} truncate`}>{text}</span>
            </div>
          );
        })}
        {n < shown.length && <div className="caret text-white/50" />}
      </div>
    </WindowFrame>
  );
}

"use client";

import type { ReactNode } from "react";
import { Moon } from "./ui";

export type PhoneNote = { title: string; body: string; time: string; tone?: "ok" | "alert" | "low" };

/** A lock-screen phone showing the pages Night Shift sends. */
export default function Phone({ notes, clock, footer }: { notes: PhoneNote[]; clock: string; footer?: ReactNode }) {
  return (
    <div className="relative mx-auto w-[260px] rounded-[38px] border border-white/15 bg-[#050506] p-3 shadow-[0_40px_120px_rgba(0,0,0,.7)]">
      <div className="absolute left-1/2 top-3 h-5 w-20 -translate-x-1/2 rounded-full bg-black" />
      <div className="dotgrid relative h-[470px] overflow-hidden rounded-[30px] bg-gradient-to-b from-[#0b0d18] to-black px-3 pt-10">
        <div className="text-center">
          <div className="text-[11px] font-medium text-white/60">Saturday, October 11</div>
          <div className="text-[56px] font-light leading-none tracking-tight text-white">{clock.slice(0, 5)}</div>
        </div>
        <div className="mt-6 space-y-2">
          {notes.length === 0 && (
            <div className="mt-16 text-center text-[12px] text-white/35">No pages. Sleep well.</div>
          )}
          {notes.slice(0, 4).map((n, i) => (
            <div
              key={`${n.title}-${i}`}
              className="slide-in rounded-2xl border border-white/10 bg-white/[0.08] p-3 backdrop-blur"
            >
              <div className="mb-1 flex items-center gap-1.5 text-[10px] uppercase tracking-wide text-white/50">
                <span className="grid h-4 w-4 place-items-center rounded bg-black">
                  <Moon size={10} />
                </span>
                Night Shift <span className="ml-auto normal-case">{n.time}</span>
              </div>
              <div
                className="text-[12.5px] font-semibold"
                style={{ color: n.tone === "alert" ? "var(--alert)" : n.tone === "low" ? "var(--amber)" : "#fff" }}
              >
                {n.title}
              </div>
              <div className="mt-0.5 line-clamp-5 text-[11.5px] leading-snug text-white/75">{n.body}</div>
            </div>
          ))}
        </div>
        {footer && <div className="absolute inset-x-3 bottom-4">{footer}</div>}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { API } from "./api";

export type Window = {
  n: number;
  correct_rate: number;
  loss_per_conv: number;
  cost_per_conv: number;
  failed_rate: number;
  wrong_refund_rate: number;
  avg_steps: number;
  trace_ids: string[];
};

export type BenchResult = {
  incident: string;
  name: string;
  story: string;
  incident_id: string | null;
  status: string | null;
  severity: string | null;
  conversations_to_detect: number;
  seconds_to_detect: number | null;
  seconds_detect_to_mitigate: number | null;
  diagnosed_type: string | null;
  expected_type: string;
  type_correct: boolean;
  culprit: string | null;
  culprit_correct: boolean;
  checkpoint: string | null;
  coding_prompt: string;
  action: string | null;
  action_mode: string | null;
  action_correct: boolean;
  replay: number | null;
  replay_n: number | null;
  live_recovered: boolean | null;
  diagnosis_method: string | null;
  diagnosis_model: string | null;
  confidence: number | null;
  nightshift_cost_usd: number;
  nightshift_trace_id: string | null;
  evidence_trace_ids: string[];
  loss_per_minute: number | null;
  projected_loss_if_waiting: number | null;
  before: Window;
  during: Window;
  after: Window;
  traffic_cost_usd: number;
  timeline: { t: number; kind: string; title: string }[];
};

export type Bench = { run: string | null; results: BenchResult[]; source: "api" | "static" | "none" };

/** Benchmark evidence: from the API when it runs, else the snapshot shipped in /public. */
export function useBenchmark(): Bench | null {
  const [data, setData] = useState<Bench | null>(null);
  useEffect(() => {
    let alive = true;
    fetch(`${API}/api/benchmark`, { cache: "no-store" })
      .then((r) => (r.ok ? r.json() : Promise.reject()))
      .then((d) => {
        if (alive && d.results?.length) setData({ ...d, source: "api" });
        else return Promise.reject();
      })
      .catch(() =>
        fetch("/benchmark.json")
          .then((r) => (r.ok ? r.json() : Promise.reject()))
          .then((d) => alive && setData({ ...d, source: "static" }))
          .catch(() => alive && setData({ run: null, results: [], source: "none" })),
      );
    return () => {
      alive = false;
    };
  }, []);
  return data;
}

