"use client";

import { OUTCOME_COLOR, money, type Conversation } from "@/lib/api";
import { Label } from "../ui";

const LABEL: Record<string, string> = {
  correct: "resolved",
  escalated: "to human",
  wrong_refund: "wrong refund",
  missed_refund: "missed refund",
  failed: "failed",
};

export default function TrafficFeed({ items }: { items: Conversation[] }) {
  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="flex items-center justify-between border-b border-line px-4 py-3">
        <Label>live customer conversations</Label>
        <span className="font-mono text-[11px] text-white/35">{items.length} shown</span>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto">
        {items.length === 0 && (
          <div className="p-6 text-center text-[13px] text-white/40">No traffic yet. Start traffic in the controls.</div>
        )}
        {items.map((c) => {
          const color = OUTCOME_COLOR[c.outcome] ?? "var(--faint)";
          return (
            <div key={c.id} className="slide-in border-b border-white/[0.04] px-4 py-2.5">
              <div className="flex items-center gap-2 font-mono text-[10.5px] text-white/35">
                <span className="h-1.5 w-1.5 rounded-full" style={{ background: color }} />
                <span>{new Date(c.ts * 1000).toLocaleTimeString([], { hour12: false })}</span>
                <span>{c.release}</span>
                <span className="truncate">{c.model}</span>
                <span className="ml-auto uppercase" style={{ color }}>
                  {LABEL[c.outcome] ?? c.outcome}
                  {c.loss_usd > 0 ? ` · −${money(c.loss_usd, 2)}` : ""}
                </span>
              </div>
              <div className="mt-1 truncate text-[12.5px] text-white/80">“{c.message}”</div>
              <div className="truncate text-[12px] text-white/40">{c.error ? `⚠ ${c.error}` : c.reply}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { money, post, short, type IncidentDetail } from "@/lib/api";
import { Button, Label, Pill } from "../ui";

const STATUS_COLOR: Record<string, string> = {
  OPEN: "var(--alert)",
  INVESTIGATING: "var(--alert)",
  MITIGATING: "var(--amber)",
  MONITORING: "var(--amber)",
  RESOLVED: "var(--ok)",
  AWAITING_HUMAN: "var(--alert)",
  ESCALATED: "var(--alert)",
  DEFERRED: "var(--amber)",
};

const KIND: Record<string, [string, string]> = {
  detect: ["DETECT", "var(--alert)"],
  investigate: ["INVESTIGATE", "var(--info)"],
  step: ["", "var(--faint)"],
  diagnosis: ["DIAGNOSIS", "var(--violet)"],
  impact: ["PRICE", "var(--amber)"],
  decide: ["POLICY", "var(--info)"],
  propose: ["PROPOSE", "var(--faint)"],
  act: ["ACT", "var(--ok)"],
  verify: ["VERIFY", "var(--ok)"],
  regression: ["TEST", "var(--faint)"],
  detection: ["NEATLOGS", "var(--faint)"],
  page: ["PAGE", "var(--amber)"],
  defer: ["DEFER", "var(--amber)"],
  resolved: ["RESOLVED", "var(--ok)"],
  undo: ["UNDO", "var(--alert)"],
};

export default function IncidentPanel({ inc, onChange }: { inc: IncidentDetail | null; onChange: () => void }) {
  if (!inc) {
    return (
      <div className="grid h-full place-items-center p-8 text-center">
        <div>
          <div className="text-[15px] text-white/80">All quiet.</div>
          <div className="mt-1 text-[13px] text-white/40">Night Shift is watching every conversation. Ship a bad release to wake it up.</div>
        </div>
      </div>
    );
  }
  const d = inc.diagnosis;
  const p = d?.provenance;
  const steps = inc.events.filter((e) => !(e.kind === "step" && e.title.startsWith("think")));
  const thoughts = inc.events.filter((e) => e.kind === "step" && e.title.startsWith("think"));
  const proposals = inc.actions.filter((a) => a.status === "proposed");
  const replay = inc.verification?.replay;

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="flex flex-wrap items-center gap-2 border-b border-line px-4 py-3">
        <Pill color={STATUS_COLOR[inc.status] ?? "var(--muted)"} pulse={["OPEN", "INVESTIGATING", "AWAITING_HUMAN"].includes(inc.status)}>
          {inc.status.replace("_", " ")}
        </Pill>
        {inc.severity && <Pill color="var(--alert)">{inc.severity}</Pill>}
        <Link href={`/incidents/${inc.id}`} className="font-mono text-[11px] text-white/40 hover:text-white">
          {inc.id} ↗
        </Link>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto px-4 py-3">
        <div className="text-[17px] font-medium tracking-tight text-white">{inc.title}</div>
        {inc.summary && <p className="mt-1 text-[13px] leading-relaxed text-white/60">{inc.summary}</p>}

        {/* Provenance */}
        {p && (
          <div className="mt-4 rounded-lg border border-violet/30 bg-violet/[0.06] p-3">
            <Label>root cause → commit → Entire checkpoint → prompt</Label>
            <div className="mt-2 font-mono text-[11.5px] text-white/70">
              {p.release} · {short(p.commit, 8)} “{p.commit_subject}” · {p.checkpoint_id}
              {p.agent ? ` · ${p.agent} ${p.model ?? ""}` : ""}
            </div>
            {(d?.coding_prompt || p.coding_prompts?.[0]) && (
              <p className="mt-2 text-[13px] leading-relaxed text-white/85">“{d?.coding_prompt || p.coding_prompts[0]}”</p>
            )}
            {p.coding_agent_note && (
              <details className="mt-2">
                <summary className="cursor-pointer text-[12px] text-amber">The coding agent warned about this. Nobody read it.</summary>
                <p className="mt-1 whitespace-pre-wrap text-[12px] leading-relaxed text-white/60">{p.coding_agent_note}</p>
              </details>
            )}
            {p.entire_url && (
              <a href={p.entire_url} target="_blank" rel="noreferrer" className="mt-2 inline-block text-[12px] text-info underline underline-offset-2">
                open checkpoint on entire.io
              </a>
            )}
          </div>
        )}

        {/* Impact + verification */}
        {(inc.impact || replay) && (
          <div className="mt-3 grid grid-cols-3 gap-2">
            <div className="rounded-lg border border-line p-2.5">
              <Label>loss rate</Label>
              <div className="mt-1 text-[18px] text-amber">{inc.impact ? `${money(inc.impact.loss_per_minute, 2)}/min` : "—"}</div>
            </div>
            <div className="rounded-lg border border-line p-2.5">
              <Label>if we waited</Label>
              <div className="mt-1 text-[18px] text-white">
                {inc.impact ? money(inc.impact.projected_loss_if_waiting) : "—"}
              </div>
              <div className="text-[10.5px] text-white/35">{inc.impact ? `${inc.impact.human_response_minutes} min to a human` : ""}</div>
            </div>
            <div className="rounded-lg border border-line p-2.5">
              <Label>replay</Label>
              <div className="mt-1 text-[18px] text-ok">{replay ? `${replay.passed}/${replay.n} pass` : "—"}</div>
            </div>
          </div>
        )}

        {/* Proposals */}
        {proposals.length > 0 && (
          <div className="mt-3 space-y-2">
            {proposals.map((a) => (
              <div key={a.id} className="flex items-start gap-3 rounded-lg border border-amber/30 bg-amber/[0.05] p-3">
                <div className="min-w-0 flex-1">
                  <Label>needs your approval · {a.kind.replaceAll("_", " ")}</Label>
                  <p className="mt-1 line-clamp-3 text-[12.5px] text-white/75">
                    {String((a.params as Record<string, unknown>).summary ?? JSON.stringify(a.params))}
                  </p>
                </div>
                <Button tone="primary" onClick={() => post(`/api/actions/${a.id}/approve`).then(onChange)}>
                  Approve
                </Button>
              </div>
            ))}
          </div>
        )}

        {/* Timeline */}
        <div className="mt-4">
          <Label>timeline</Label>
          <div className="mt-2 space-y-1.5 font-mono text-[11.5px]">
            {steps.map((e) => {
              const [tag, color] = KIND[e.kind] ?? [e.kind.toUpperCase(), "var(--faint)"];
              const isStep = e.kind === "step";
              return (
                <div key={e.id} className="slide-in flex gap-2">
                  <span className="shrink-0 text-white/30">{new Date(e.ts * 1000).toLocaleTimeString([], { hour12: false })}</span>
                  <span className="w-[78px] shrink-0" style={{ color }}>{isStep ? "  ↳ tool" : tag}</span>
                  <span className={isStep ? "text-white/45" : "text-white/85"}>{e.title}</span>
                </div>
              );
            })}
          </div>
          {thoughts.length > 0 && (
            <details className="mt-3">
              <summary className="cursor-pointer font-mono text-[11px] text-white/40">investigator reasoning ({thoughts.length})</summary>
              <div className="mt-2 space-y-2">
                {thoughts.map((t) => (
                  <p key={t.id} className="whitespace-pre-wrap text-[12px] leading-relaxed text-white/55">
                    {t.title.replace(/^think:\s*/, "")}
                  </p>
                ))}
              </div>
            </details>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { post, type Release, type State } from "@/lib/api";
import { Button, Label } from "../ui";

export default function Controls({ state, releases, onChange }: { state: State | null; releases: Release[]; onChange: () => void }) {
  const [busy, setBusy] = useState<string | null>(null);
  const run = (key: string, fn: () => Promise<unknown>) => {
    setBusy(key);
    fn()
      .catch((e) => alert(String(e)))
      .finally(() => {
        setBusy(null);
        onChange();
      });
  };
  const traffic = state?.traffic;
  const outage = (state?.outage_models ?? []).length > 0;
  const attack = (traffic?.attack_share ?? 0) > 0;
  const bad = releases.filter((r) => r.id !== "r41");

  return (
    <div className="space-y-5 p-4">
      <div>
        <Label>customer traffic</Label>
        <div className="mt-2 flex flex-wrap gap-2">
          <Button
            tone={traffic?.running ? "default" : "primary"}
            disabled={busy === "traffic"}
            onClick={() => run("traffic", () => post("/api/traffic", { running: !traffic?.running }))}
          >
            {traffic?.running ? "Pause traffic" : "Start traffic"}
          </Button>
          {[6, 12, 24].map((pm) => (
            <Button
              key={pm}
              tone={traffic?.per_minute === pm ? "ok" : "default"}
              onClick={() => run("rate", () => post("/api/traffic", { running: true, per_minute: pm }))}
            >
              {pm}/min
            </Button>
          ))}
        </div>
      </div>

      <div>
        <Label>ship a release (each written by a Claude Code session)</Label>
        <div className="mt-2 space-y-1.5">
          {bad.map((r) => (
            <button
              key={r.id}
              disabled={busy !== null || state?.release === r.id}
              onClick={() => run(r.id, () => post("/api/demo/deploy", { release: r.id }))}
              className="group block w-full rounded-md border border-line bg-white/[0.02] px-3 py-2 text-left transition hover:border-alert/50 hover:bg-alert/[0.06] disabled:opacity-40"
            >
              <div className="flex items-center gap-2 text-[12.5px] text-white">
                <span className="font-mono text-white/40">{r.id}</span> {r.title}
                {state?.release === r.id && <span className="ml-auto font-mono text-[10px] text-alert">LIVE</span>}
              </div>
              {r.provenance?.checkpoint_id && (
                <div className="mt-0.5 truncate font-mono text-[10px] text-white/30">
                  checkpoint {r.provenance.checkpoint_id} · {r.provenance.agent} {r.provenance.model}
                </div>
              )}
            </button>
          ))}
          <Button
            className="w-full"
            disabled={busy !== null || state?.release === "r41"}
            onClick={() => run("r41", () => post("/api/demo/deploy", { release: "r41", actor: "human" }))}
          >
            Deploy r41 (known-good) by hand
          </Button>
        </div>
      </div>

      <div>
        <Label>chaos</Label>
        <div className="mt-2 flex flex-wrap gap-2">
          <Button
            tone={outage ? "danger" : "default"}
            onClick={() => run("outage", () => post("/api/demo/fault", { kind: "provider_outage", value: outage ? null : "claude-haiku" }))}
          >
            {outage ? "End provider outage" : "Provider outage"}
          </Button>
          <Button
            tone={attack ? "danger" : "default"}
            onClick={() => run("attack", () => post("/api/demo/attack", { share: attack ? 0 : 0.5 }))}
          >
            {attack ? "Stop attack wave" : "Prompt-injection wave"}
          </Button>
        </div>
      </div>

      <div>
        <Label>night shift</Label>
        <div className="mt-2 flex flex-wrap gap-2">
          <Button
            tone={state?.nightshift_enabled ? "ok" : "danger"}
            onClick={() => run("ns", () => post("/api/nightshift", { enabled: !state?.nightshift_enabled }))}
          >
            {state?.nightshift_enabled ? "On call ✓" : "Off duty — click to enable"}
          </Button>
          <Button
            onClick={() => {
              if (confirm("Reset the demo? This clears conversations and incidents.")) run("reset", () => post("/api/demo/reset"));
            }}
          >
            Reset demo
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import Controls from "@/components/console/Controls";
import IncidentPanel from "@/components/console/IncidentPanel";
import TrafficFeed from "@/components/console/TrafficFeed";
import NightSky from "@/components/NightSky";
import Phone, { type PhoneNote } from "@/components/Phone";
import { Counter, Label, Moon, Pill, Sparkline } from "@/components/ui";
import {
  API,
  get,
  money,
  usePoll,
  useStream,
  type Conversation,
  type IncidentDetail,
  type IncidentRow,
  type Release,
  type State,
} from "@/lib/api";

type Metrics = { bucket_s: number; series: { t: number; n: number; loss: number; cost: number; failed: number; wrong_refund: number; escalated: number; correct: number }[] };

export default function ConsolePage() {
  const [state, stateErr, reloadState] = usePoll<State>("/api/state", 2000);
  const [metrics] = usePoll<Metrics>("/api/metrics?minutes=20&bucket_s=20", 4000);
  const [releases] = usePoll<Release[]>("/api/releases", 60000);
  const [incidents, , reloadIncidents] = usePoll<IncidentRow[]>("/api/incidents", 3000);
  const [feed, setFeed] = useState<Conversation[]>([]);
  const [inc, setInc] = useState<IncidentDetail | null>(null);

  useEffect(() => {
    get<Conversation[]>("/api/conversations?limit=40").then(setFeed).catch(() => {});
  }, []);

  const currentId = state?.open_incident?.id ?? incidents?.[0]?.id ?? null;
  const loadIncident = useCallback(() => {
    if (!currentId) {
      setInc(null);
      return;
    }
    get<IncidentDetail>(`/api/incidents/${currentId}`).then(setInc).catch(() => {});
  }, [currentId]);
  useEffect(() => {
    loadIncident();
    const t = setInterval(loadIncident, 2000);
    return () => clearInterval(t);
  }, [loadIncident]);

  const connected = useStream((e) => {
    if (e.type === "conversation") {
      setFeed((f) => [e.conversation as Conversation, ...f].slice(0, 60));
    } else if (e.type === "incident_event" || e.type === "incident_update") {
      loadIncident();
      reloadIncidents();
    } else if (e.type === "reset") {
      setFeed([]);
      setInc(null);
      reloadIncidents();
    }
  });

  const series = metrics?.series ?? [];
  const lossSeries = series.map((s) => s.loss);
  const okSeries = series.map((s) => (s.n ? s.correct / s.n : 1));
  const status = state?.open_incident?.status;
  const alert = status && ["OPEN", "INVESTIGATING", "AWAITING_HUMAN", "ESCALATED"].includes(status);
  const mitigating = status && ["MITIGATING", "MONITORING"].includes(status);

  const notes: PhoneNote[] = useMemo(() => {
    if (!inc) return [];
    return inc.events
      .filter((e) => e.kind === "page" && e.detail && (e.detail as Record<string, unknown>).body)
      .reverse()
      .map((e) => {
        const d = e.detail as Record<string, string>;
        return {
          title: d.title,
          body: d.body,
          time: new Date(e.ts * 1000).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: false }),
          tone: d.title.startsWith("✅") ? "ok" : d.title.startsWith("🌙") ? "low" : "alert",
        } as PhoneNote;
      });
  }, [inc]);

  const recent = feed.slice(0, 20);
  const recentLoss = recent.reduce((a, c) => a + (c.loss_usd || 0), 0);

  return (
    <main className="flex min-h-screen flex-col">
      {/* Top bar */}
      <header className="flex flex-wrap items-center gap-x-6 gap-y-2 border-b border-line px-4 py-3 sm:px-6">
        <Link href="/" className="flex items-center gap-2 text-[15px] font-semibold text-white">
          <Moon /> night shift
        </Link>
        <span className="font-mono text-[12px] text-white/40">console</span>
        <div className="flex items-baseline gap-2">
          <span className="font-mono text-[22px] font-light tabular-nums text-white">{state?.local_time ?? "--:--:--"}</span>
          {state?.local_time_simulated && <span className="font-mono text-[10px] text-white/35">simulated local time</span>}
        </div>
        {alert ? (
          <Pill color="var(--alert)" pulse>
            incident · {state?.open_incident?.severity ?? "…"}
          </Pill>
        ) : mitigating ? (
          <Pill color="var(--amber)">mitigated · watching</Pill>
        ) : (
          <Pill color="var(--ok)">all clear</Pill>
        )}
        <div className="font-mono text-[11.5px] text-white/50">
          release <span className="text-white">{state?.release ?? "—"}</span> · model{" "}
          <span className="text-white">{state?.model ?? "—"}</span>
          {state?.flags && state.flags.auto_refund_enabled === false && <span className="text-amber"> · auto-refunds off</span>}
        </div>
        <div className="ml-auto flex items-center gap-3 font-mono text-[11px] text-white/40">
          <span>{state?.brain === "sim" ? "SIM brain (offline)" : "LIVE models"}</span>
          {state?.budget?.available && (
            <span>
              gateway {money(state.budget.spend, 2)} / {money(state.budget.max_budget)}
            </span>
          )}
          <span className={connected ? "text-ok" : "text-alert"}>{connected ? "● stream" : "○ offline"}</span>
        </div>
      </header>

      {stateErr && (
        <div className="border-b border-alert/30 bg-alert/10 px-6 py-2 text-[12.5px] text-alert">
          Can’t reach the Night Shift API at {API}. Start it with <code className="font-mono">uv run uvicorn api.server:app</code> in /backend.
        </div>
      )}

      <div className="grid min-h-0 flex-1 gap-px bg-line lg:grid-cols-[minmax(0,1fr)_minmax(0,1.25fr)_340px]">
        {/* Left: money + feed */}
        <section className="flex min-h-[520px] flex-col bg-bg">
          <div className="relative overflow-hidden border-b border-line px-4 py-5">
            <NightSky alert={alert ? 1 : 0} className="opacity-40" />
            <div className="relative">
              <Label>lost in the last {recent.length || 0} conversations</Label>
              <div className={`mt-1 text-[44px] font-light tabular-nums tracking-tight ${recentLoss > 0 ? "text-alert" : "text-white"}`}>
                <Counter value={recentLoss} format={(v) => money(v, 2)} />
              </div>
              <div className="mt-1 font-mono text-[11px] text-white/40">
                all time {money(state?.totals?.loss ?? 0, 0)} lost · {state?.totals?.n ?? 0} conversations · LLM {money(state?.totals?.cost ?? 0, 2)}
              </div>
              <div className="mt-4">
                <div className="mb-1 flex justify-between font-mono text-[10px] text-white/35">
                  <span>loss per 20s</span>
                  <span>last 20 min</span>
                </div>
                <Sparkline values={lossSeries} color="var(--alert)" height={50} />
                <div className="mt-2 mb-1 font-mono text-[10px] text-white/35">resolved correctly</div>
                <Sparkline values={okSeries} color="var(--ok)" height={30} fill={false} />
              </div>
            </div>
          </div>
          <div className="min-h-0 flex-1">
            <TrafficFeed items={feed} />
          </div>
        </section>

        {/* Center: incident */}
        <section className="min-h-[520px] bg-bg">
          <IncidentPanel inc={inc} onChange={() => { loadIncident(); reloadState(); }} />
        </section>

        {/* Right: phone + controls */}
        <aside className="bg-bg">
          <div className="border-b border-line py-5">
            <Phone notes={notes} clock={state?.local_time ?? "03:07"} />
          </div>
          <Controls state={state} releases={releases ?? []} onChange={reloadState} />
        </aside>
      </div>
    </main>
  );
}

